using System;using System.Collections.Generic;using System.IO;using System.Text;using System.Windows.Forms;using F=SolidEdgeFramework;using A=SolidEdgeAssembly;
namespace TianGongPanel {
public sealed class LineupItem { public object Model; public string 编号,地址,功能参数,描述,型号,品牌,原位,安装方式,机构名称,传感器接口类型,备注,所属阀岛,所属阀片,模型标识; public override string ToString(){return (编号??"")+"  "+(描述??"")+"  "+(型号??"");} public string[] Cells(){return new[]{编号,地址,功能参数,描述,型号,品牌,原位,安装方式,机构名称,传感器接口类型,备注,所属阀岛,所属阀片,模型标识};} }
public sealed class LineupForm:Form { readonly List<LineupItem> items=new List<LineupItem>(); readonly ListBox list=new ListBox(); object selectedModel; readonly F.Application app; readonly A.AssemblyDocument assembly; readonly TextBox[] boxes=new TextBox[14]; readonly string[] names={"编号","地址","功能参数","描述","型号","品牌","原位","安装方式","机构名称","传感器接口类型","备注","所属阀岛","所属阀片","模型标识"}; string StorePath{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"TianGongPanel","lineup.csv");}} public LineupForm(F.Application a,A.AssemblyDocument d){app=a;assembly=d;assembly=d;Text="Lineup 模型标记";Width=760;Height=560;var filter=new TextBox{Dock=DockStyle.Top};Controls.Add(filter);filter.TextChanged+=(x,e)=>ApplyFilter(filter.Text);var s=new SplitContainer{Dock=DockStyle.Fill,SplitterDistance=260};Controls.Add(s);s.Dock=DockStyle.Fill;list.Dock=DockStyle.Fill;s.Panel1.Controls.Add(list);list.SelectedIndexChanged+=(x,e)=>HighlightSelected();var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new Padding(8)};p.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,120));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));s.Panel2.Controls.Add(p);for(int i=0;i<names.Length;i++){p.Controls.Add(new Label{Text=names[i],Dock=DockStyle.Fill},0,i);boxes[i]=new TextBox{Dock=DockStyle.Fill};p.Controls.Add(boxes[i],1,i);}var b=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=42};var pick=new Button{Text="读取当前选择"};pick.Click+=(x,e)=>Pick();var del=new Button{Text="删除标记"};del.Click+=(x,e)=>DeleteItem();var add=new Button{Text="新增/保存标记"};add.Click+=(x,e)=>SaveItem();var imp=new Button{Text="导入 CSV"};imp.Click+=(x,e)=>Import();var fit=new Button{Text="定位并适配视图"};fit.Click+=(x,e)=>{HighlightSelected();FitView();};var clear=new Button{Text="清除高亮"};clear.Click+=(x,e)=>ClearHighlight();var exp=new Button{Text="导出 CSV"};exp.Click+=(x,e)=>Export();b.Controls.Add(pick);b.Controls.Add(del);b.Controls.Add(add);b.Controls.Add(imp);b.Controls.Add(fit);b.Controls.Add(clear);b.Controls.Add(exp);s.Panel2.Controls.Add(b);LoadStore();} void LoadStore(){try{if(!File.Exists(StorePath))return;foreach(var line in File.ReadAllLines(StorePath,Encoding.UTF8)){if(string.IsNullOrWhiteSpace(line)||line.StartsWith("编号"))continue;var c=line.Split(',');var x=new LineupItem();for(int i=0;i<Math.Min(c.Length,names.Length);i++)typeof(LineupItem).GetField(names[i]).SetValue(x,c[i].Trim('"'));items.Add(x);list.Items.Add(x);}}catch{}} string asmPathSafe(){try{return assembly.Path;}catch{return "<active-assembly>";}} void ApplyFilter(string q){list.Items.Clear();foreach(var x in items){var t=x.ToString()+" "+(x.机构名称??"");if(string.IsNullOrWhiteSpace(q)||t.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0)list.Items.Add(x);}} void Pick(){try{dynamic set=app.ActiveSelectSet;if(set.Count<1){MessageBox.Show("请先在 CAD 中选择模型。");return;}dynamic o=set.Item(1);boxes[13].Text=(asmPathSafe()+"|"+(o.Name??o.ToString())); selectedModel=o;}catch(Exception e){MessageBox.Show("读取选择失败："+e.Message);}}   void FitView(){try{dynamic w=app.ActiveWindow;w.View.Fit();}catch{}} void HighlightSelected(){try{var x=list.SelectedItem as LineupItem;if(x==null||x.Model==null)return;dynamic h=assembly.HighlightSets.Add();h.Color=0x00FFFF;h.AddItem(x.Model);h.Draw();}catch{}} void ClearHighlight(){try{foreach(dynamic h in assembly.HighlightSets)h.Delete();}catch{}} void Import(){using(var d=new OpenFileDialog{Filter="CSV 文件|*.csv"})if(d.ShowDialog(this)==DialogResult.OK){foreach(var line in File.ReadAllLines(d.FileName,Encoding.UTF8)){if(string.IsNullOrWhiteSpace(line)||line.StartsWith("编号"))continue;var c=line.Split(',');var x=new LineupItem();for(int i=0;i<Math.Min(c.Length,boxes.Length);i++)typeof(LineupItem).GetField(names[i]).SetValue(x,c[i].Trim('"'));items.Add(x);list.Items.Add(x);}}} void DeleteItem(){var x=list.SelectedItem as LineupItem;if(x!=null){items.Remove(x);list.Items.Remove(x);SaveStore();}} void SaveItem(){if(string.IsNullOrWhiteSpace(boxes[0].Text)){MessageBox.Show("编号不能为空。","Lineup");return;}foreach(var old in items)if(old.编号==boxes[0].Text && old!=list.SelectedItem){MessageBox.Show("编号重复："+boxes[0].Text,"Lineup");return;}var x=new LineupItem();x.Model=selectedModel;for(int i=0;i<boxes.Length;i++)typeof(LineupItem).GetField(names[i]).SetValue(x,boxes[i].Text);items.Add(x);list.Items.Add(x);SaveStore();} void SaveStore(){try{Directory.CreateDirectory(Path.GetDirectoryName(StorePath));var sb=new StringBuilder();sb.AppendLine(string.Join(",",names));foreach(var x in items){var c=x.Cells();for(int i=0;i<c.Length;i++)c[i]="\\\""+(c[i]??"").Replace("\\\"","\\\"\\\"")+"\\\"";sb.AppendLine(string.Join(",",c));}File.WriteAllText(StorePath,sb.ToString(),Encoding.UTF8);}catch{}} void Export(){using(var d=new SaveFileDialog{Filter="CSV 文件|*.csv",FileName="Lineup.csv"})if(d.ShowDialog(this)==DialogResult.OK){var sb=new StringBuilder();sb.AppendLine(string.Join(",",names));foreach(var x in items){var c=x.Cells();for(int i=0;i<c.Length;i++)c[i]="\""+(c[i]??"").Replace("\"","\"\"")+"\"";sb.AppendLine(string.Join(",",c));}File.WriteAllText(d.FileName,sb.ToString(),Encoding.UTF8);MessageBox.Show("已导出");}} }
}
















